class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def equals(self, other):
        if self.name == other.name and self.age == other.age:
            return True
        return False

def main():
    line1 = input().strip()
    line2 = input().strip()

    parts1 = line1.split()
    parts2 = line2.split()

    name1 = parts1[0]
    age1 = int(parts1[1])

    name2 = parts2[0]
    age2 = int(parts2[1])

    p1 = Person(name1, age1)
    p2 = Person(name2, age2)

    if p1.equals(p2):
        print("Equal")
    else:
        print("Not Equal")

if __name__ == "__main__":
    main()
